class MainDialog : public ncdfDialog {
public:
	MainDialog( wxWindow *parent );
	virtual ~MainDialog();

	ncdfReader 	*my_ncdfReader;

	void SetCursorLatLon(double lat, double lon);
	void setPlugIn(ncdf_pi *p);

	ncdf_pi	*pPlugIn;
	wxWindow	*m_parent;
	Selection	selectionRectangle;
	double		m_cursor_lon, m_cursor_lat;
	double *my_ucurr = 0;
	double *my_vcurr = 0;
	int treeMinutes[96];

	// Lightweight file metadata (for tree building, no data allocation)
	struct FileMetadata {
		bool valid;
		bool hasCurrent, hasSeaTemp, hasSalinity, hasZos;
		size_t timelength, latlength, lonlength;
		wxDouble firstGridPointLat, firstGridPointLong;
		wxDouble lastGridPointLat, lastGridPointLong;
		wxDouble iDirectionIncr, jDirectionIncr;
		int cached_u_varid, cached_v_varid, cached_sst_varid, cached_sal_varid, cached_zos_varid;
		std::vector<wxDateTime> dates;
		std::vector<bool> timeValid;
		std::vector<double> timeValues;
		std::shared_ptr<SharedCoords> sharedCoords;
		FileMetadata() : valid(false), hasCurrent(false), hasSeaTemp(false), hasSalinity(false), hasZos(false),
			timelength(0), latlength(0), lonlength(0),
			firstGridPointLat(0), firstGridPointLong(0),
			lastGridPointLat(0), lastGridPointLong(0),
			iDirectionIncr(0), jDirectionIncr(0),
			cached_u_varid(-1), cached_v_varid(-1),
			cached_sst_varid(-1), cached_sal_varid(-1), cached_zos_varid(-1) {}
	};
	FileMetadata nc_read_metadata(const wxString &fileName);

	bool m_fileHasCurrent = false;   // File contains u/v ocean current data
	bool m_fileHasSeaTemp = false;   // File contains SST data
	bool m_fileHasSalinity = false;  // File contains salinity data
	bool m_fileHasZos = false;       // File contains sea surface height data
	int m_cached_u_varid = -1;       // Cached NetCDF variable ID for u-current
	int m_cached_v_varid = -1;       // Cached NetCDF variable ID for v-current
	int m_cached_sst_varid = -1;     // Cached NetCDF variable ID for SST
	int m_cached_sal_varid = -1;     // Cached NetCDF variable ID for salinity
	int m_cached_zos_varid = -1;     // Cached NetCDF variable ID for zos

	// Persistent NetCDF file handle (reused across same-file time step switches)
	int m_openedNcid = -1;
	wxString m_openedFileName;

	// Pre-allocated data buffers (file-level, reused across time steps to avoid 32-bit heap fragmentation)
	std::vector<double> m_fileUBuffer;
	std::vector<double> m_fileVBuffer;
	std::vector<double> m_fileSSTBuffer;
	std::vector<double> m_fileSalBuffer;
	std::vector<double> m_fileZosBuffer;
	bool m_fileBufferReady;

	ncdfDataMessage myncdfData, myData, myMessage;
	vector<ncdfDataMessage> myDataVector;
	int m_lastSelectedTimeIndex;
	int ncdf_get_data(wxString filestr);
	int ncdf_get_keys(wxString filestr);
	int nc_get(wxString filestr);

	int ncdf_get_ncdf1();
	double** makeGridDataCURRENT(ncdfDataMessage message, wxString current);
	int np;
	void OnContextMenu(double m_lat, double m_lon);
	void BuildHelpPage();
	CurrentData getCurrentData(double lat, double lon);
	std::list<Arrow*> m_ArrowList;
	
	bool readTimeStepData(ncdfDataMessage& dataMessage);
	bool m_isTreeUpdating;
	bool m_isLoading{false};  // Guard against re-entrant time step loads
	bool m_dataLoaded{false};  // True when myMessage has data for current time step
	bool m_gridsReady{false};  // True when float grids are prepared (Phase 2 complete)
	wxString m_currentFilePath;  // Track which file is currently loaded


private:
	void UpdateTrackingControls();
	void printCurrentData();
	bool switchToFile(const wxString &fileName, const wxString &fn, int &idx);



	wxString toBeaufort(wxFloat32 w);
	wxLogWindow *log_window_m;



protected:
	// protected event handlers
	virtual void OnCloseFrame( wxCloseEvent& event );
	virtual void onCloseDialog( wxCloseEvent& event );
	virtual void OnExitClick( wxCommandEvent& event );
	virtual void onFileButtonClick(wxCommandEvent& event);



	wxDateTime GetDateFromHours(int hours_in);

	virtual void onDirChanged(wxCommandEvent& event);
	virtual void onTreeSelectionChanged(wxTreeEvent& event);
	virtual void onTreeItemRightClick(wxTreeEvent& event);
	virtual void onDCurrentClick( wxCommandEvent& event );
	virtual void onBmpCurrentForceClick( wxCommandEvent& event );
	virtual void onParticlesClick( wxCommandEvent& event );
	virtual void onSeaTempClick( wxCommandEvent& event );
	virtual void onSalinityClick( wxCommandEvent& event );
	virtual void onZosClick( wxCommandEvent& event );
	virtual void onAnimateClick( wxCommandEvent& event );
	virtual void onAnimateSSTClick( wxCommandEvent& event );
	virtual void onAnimateSalClick( wxCommandEvent& event );
	virtual void onAnimateZosClick( wxCommandEvent& event );
	virtual void onIsoSSTClick( wxCommandEvent& event );
	virtual void onIsoSalClick( wxCommandEvent& event );
	virtual void onIsoZosClick( wxCommandEvent& event );
	// Feature detection (识别 tab)
	virtual void onFeatClipClick( wxCommandEvent& event );
	virtual void onFeatFrontClick( wxCommandEvent& event );
	virtual void onFeatEddyClick( wxCommandEvent& event );
	virtual void onFeatJetClick( wxCommandEvent& event );
	virtual void onFeatRegionPick( wxCommandEvent& event );
	virtual void onFeatConvergClick( wxCommandEvent& event );
	virtual void onFeatShearClick( wxCommandEvent& event );
	virtual void onFeatROIChoice( wxCommandEvent& event );
	virtual void onFeatRegionApply( wxCommandEvent& event );
	virtual void onFeatSensChanged( wxScrollEvent& event );
	// 黑潮主轴提取（流线约束最大流速法，Wang2026）
	virtual void onKuroshioExtractClick( wxCommandEvent& event );
	virtual void onKuroshioExportClick( wxCommandEvent& event );
	virtual void onKuroshioShowClick( wxCommandEvent& event );
	virtual void onKuroshioBdyClick( wxCommandEvent& event );
	virtual void onSeamtPresetChoice( wxCommandEvent& event );
	virtual void onSeamtExtractClick( wxCommandEvent& event );
	virtual void onSeamtExportClick( wxCommandEvent& event );
	virtual void onSeamtParamChanged( wxCommandEvent& event );
	virtual void onSeamtShowClick( wxCommandEvent& event );
	virtual void onSeamtSubjetsClick( wxCommandEvent& event );
public:
	// 黑潮主轴提取结果（每次提取覆盖；渲染线程只读）
	KuroshioExtractor m_kuroshio;
	KuroshioAxisResult m_kuroshioResult;
	bool m_kuroshioNeedUV = false;      // 为提取主轴强制读入 U/V（不依赖“显示流速”勾选）

	// SEAMT 急流核心提取（Udalov2026，黑潮**下游**：日本以南 / 延伸体）。
	// 与上面的 Wang2026（上游 115–132°E，A–E 断面硬编码）完全独立，
	// 适用域不重叠，**不要混用**。见 docs/SEAMT急流核心提取-方法论与实现方案.md §0.2
	SeamtExtractor m_seamt;
	SeamtResult    m_seamtResult;
	bool runSeamtExtract();
	bool exportSeamtCsv();
	void syncSeamtParamsFromUi();       // 读 UI 框 -> m_seamt.params
	void applySeamtPreset(int which);   // 0=日本以南 1=论文原域 2=自定义（只填框）
	// 提取用完后归还 U/V 原始双精度内存（与 Phase 2 的内存纪律一致）。
	// 渲染用的是 float 网格，这些双精度数组只给提取器；必须 swap-with-empty，
	// clear() 不归还容量（CLAUDE.md 已记该坑）。
	void releaseRawUv();

	// 自动化测试：启动时发现请求文件就自动跑一遍 SEAMT + 全套自检，
	// 结果写 ncdf_seamt_auto_result.txt。见 docs/SEAMT急流核心提取-方法论与实现方案.md
	void maybeRunSeamtAutoTest();
	void runSeamtAutoTest(const wxString &reqPath);
	// 陆海掩膜实体在 ncdf_pi::m_landMask（含粗层回退），跟随面板显示加载
	bool loadLandMask(bool verbose);
	bool ensureLandMaskVisible();   // 面板打开时调用：载入并刷新状态
	void updateLandMaskStatus();
	void ensureLandMaskForCurrentFile(const ncdfDataMessage &m);
	bool runKuroshioExtract();          // 需已加载当前时间步 U/V；失败时给出原因
	bool exportKuroshioCsv();           // 导出 主轴/左/右 边界 CSV
	void applyFeatureRegion();          // parse UI fields -> engine region
	void syncFeatureEngine();           // push plugin flags -> engine
	bool onCanvasMouse(wxMouseEvent& event);   // MouseEventHook target (P2)
	bool hitTestFeatureAt(int sx, int sy, wxString &panel);   // icon click hit test
	bool m_regionPickMode = false;
	bool m_rpDragging = false;
	int  m_rpX0 = 0, m_rpY0 = 0;
	double m_selFeatLon = -9999, m_selFeatLat = -9999;   // selected feature highlight
	void showFeaturePopup(int canvasX, int canvasY, const wxString &panel);   // popup at icon
	void updateFeaturePopupPos(PlugIn_ViewPort *vp);   // keep popup glued to its feature
	wxWindow *m_featPopup = nullptr;
	void queueFeatureRefresh(int waves); // debounced recompute (v1.1)
	wxTimer m_featDebounce;
	int m_featPendingWaves = 0;
	void fillDirTree(wxString dir, bool start, wxTreeItemId id);
	void addChildren(wxTreeItemId id, wxString s);
	void readData(wxTreeItemId itemId);
	// 目录树懒加载：文件节点先只列名字，展开时才读该 nc 的元数据。
	// 不这么做的话，面板一打开就要 nc_open 目录里每一个文件 ——
	// 2026-10-29 实测某个 130 MB 的 HDF5 文件（76863 个数据集）一次 nc_open
	// 就吃掉 1.3 GB 虚拟地址空间，把 Win32 的 2 GB 打穿后抛 bad_alloc，
	// 之后所有 nc_open 全废，进而把整个面板拖死。
	void onTreeItemExpanding(wxTreeEvent& event);

};

// MyTreeItemData::m_index 的语义：
//   >=0  时间步下标（myDataVector 的下标）
//   kFileNodeUnloaded  文件节点，元数据尚未读取
//   kFileNodeLoaded    文件节点，元数据已读取
enum {
	kFileNodeUnloaded = -2,
	kFileNodeLoaded   = -3
};

class MyTreeItemData : public wxTreeItemData
{
public:
	MyTreeItemData(int index) : m_index(index) {}
	int m_index;
};


